/**
 * CookieLens — Netscape HTTP Cookie File format.
 *
 * Seven TAB-separated fields per line:
 *   domain, includeSubdomains, path, secure, expiry, name, value
 * includeSubdomains is the INVERSE of hostOnly. HttpOnly lines carry the
 * "#HttpOnly_" prefix. Session cookies are exported with a 1-day TTL.
 */

const HEADER_LINES = [
  '# Netscape HTTP Cookie File',
  '# http://curl.haxx.se/rfc/cookie_spec.html',
  '# This file was generated by CookieLens',
];

const HTTPONLY_PREFIX = '#HttpOnly_';
const SESSION_TTL_SECONDS = 86400;

/**
 * Serialize cookies to the Netscape cookie file format.
 * @param {Array<object>} cookies
 * @returns {string}
 */
export function serialize(cookies) {
  const lines = [...HEADER_LINES];
  const sessionExpiry = Math.floor(Date.now() / 1000) + SESSION_TTL_SECONDS;

  for (const cookie of cookies) {
    const expiry = cookie.session || cookie.expirationDate == null
      ? sessionExpiry
      : Math.floor(Number(cookie.expirationDate));
    const fields = [
      cookie.domain ?? '',
      cookie.hostOnly ? 'FALSE' : 'TRUE',
      cookie.path || '/',
      cookie.secure ? 'TRUE' : 'FALSE',
      String(expiry),
      cookie.name,
      cookie.value ?? '',
    ];
    const prefix = cookie.httpOnly ? HTTPONLY_PREFIX : '';
    lines.push(prefix + fields.join('\t'));
  }
  return lines.join('\n');
}

/**
 * Parse a Netscape cookie file.
 * @param {string} text
 * @returns {Array<object>} normalized cookies
 * @throws {Error} with a user-friendly message
 */
export function parse(text) {
  const cookies = [];

  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line) {
      continue;
    }

    let httpOnly = false;
    let content = line;
    if (line.startsWith(HTTPONLY_PREFIX)) {
      httpOnly = true;
      content = line.slice(HTTPONLY_PREFIX.length);
    } else if (line.startsWith('#')) {
      continue;
    }

    const fields = content.split('\t');
    if (fields.length < 7) {
      throw new Error('Invalid Netscape format.');
    }
    const [domain, includeSubdomains, path, secure, expiry, name, value] = fields;
    const expirySeconds = parseInt(expiry, 10);
    const session = !Number.isFinite(expirySeconds) || expirySeconds <= 0;

    cookies.push({
      name,
      value,
      domain,
      hostOnly: includeSubdomains.trim().toUpperCase() !== 'TRUE',
      path: path || '/',
      secure: secure.trim().toUpperCase() === 'TRUE',
      session,
      expirationDate: session ? undefined : expirySeconds,
      httpOnly,
      sameSite: 'unspecified',
    });
  }

  if (cookies.length === 0) {
    throw new Error('No cookies found.');
  }
  return cookies;
}
